package com.projetok.studio;
import javax.swing.*;
import java.nio.file.*;
import java.util.*;

/** Biblioteca local de modelos independentes com miniatura, duplicacao e edicao. */
final class PrefabTools {
    final WorldStudio ui;final Path folder;
    PrefabTools(WorldStudio ui){this.ui=ui;folder=ui.project.resolve("studio-projects/prefabs");ui.action("Prefabs","Criar da selecao",this::save);for(String name:new String[]{"Inserir","Editar","Duplicar"})ui.action("Prefabs",name+" prefab",()->browse(name));}
    void save(){String id=JOptionPane.showInputDialog(ui,"ID do prefab");if(id==null)return;var d=Prefabs.capture(ui.document,ui.canvas.selected,id);Path target=folder.resolve(id+".sgmap");if(Files.exists(target))throw new IllegalArgumentException("Prefab existente; use Editar");write(target,d);}
    void write(Path target,WorldDocument d){new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{DocumentStore.save(target,d);return null;}protected void done(){try{get();ui.status.setText("Prefab salvo: "+target);}catch(Exception error){ui.error(error);}}}.execute();}
    void browse(String action){Map<Path,ImageIcon> thumbs=new HashMap<>();new SwingWorker<Map<Path,WorldDocument>,Void>(){protected Map<Path,WorldDocument> doInBackground()throws Exception{Map<Path,WorldDocument> result=new LinkedHashMap<>();if(!Files.exists(folder))return result;try(var files=Files.list(folder)){for(Path p:files.filter(f->f.toString().endsWith(".sgmap")).limit(256).toList()){var d=DocumentStore.load(p);result.put(p,d);for(var e:d.elements()){var a=ui.catalog.byId().get(e.asset());if(a!=null)ui.images.load(a);}thumbs.put(p,new ImageIcon(Prefabs.preview(d,ui.images)));}}return result;}protected void done(){try{var docs=get();if(docs.isEmpty())throw new IllegalArgumentException("Biblioteca vazia");JList<Path> list=new JList<>(docs.keySet().toArray(Path[]::new));list.setCellRenderer((l,p,i,s,f)->{JLabel label=new JLabel(p.getFileName().toString(),thumbs.get(p),SwingConstants.LEFT);label.setOpaque(true);label.setBackground(s?new java.awt.Color(180,210,225):java.awt.Color.WHITE);return label;});list.setSelectedIndex(0);JScrollPane scroll=new JScrollPane(list);scroll.setPreferredSize(new java.awt.Dimension(420,420));if(JOptionPane.showConfirmDialog(ui,scroll,action+" prefab",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;Path path=list.getSelectedValue();var d=docs.get(path);switch(action){case "Inserir"->{ui.change(Prefabs.insert(ui.document,d,Math.max(0,ui.lastCursor.x),Math.max(0,ui.lastCursor.y)));ui.warmImages();}case "Editar"->ui.fileTools.confirm(()->ui.fileTools.load(path,false));case "Duplicar"->{String id=d.id()+"_"+UUID.randomUUID().toString().substring(0,6);write(folder.resolve(id+".sgmap"),new WorldDocument(1,id,id,d.region(),d.width(),d.height(),d.grid(),d.layers(),d.elements(),d.hitboxes(),d.portals(),d.triggers(),d.metadata()));}default->throw new IllegalArgumentException("Acao desconhecida");}}catch(Exception error){ui.error(error);}}}.execute();}
}
